        if(context.Model.ConnectionId is not{} connectionId)return Failure("coder_provider_failed","The selected Coder model has no provider connection.");var adapter=adapters.SingleOrDefault(x=>x.ProviderType==context.Model.ProviderType);if(adapter is null)return Failure("coder_provider_failed","The selected Coder provider is unavailable.");var credential=await credentials.RetrieveAsync(connectionId,ct);if(credential.Status!=ProviderCredentialReadStatus.Found)return Failure("coder_provider_failed",credential.SafeFailureMessage??"Coder credentials are unavailable.");
        var prompt=Load("coder-v1");var transcript=new List<object>();var totalInput=0;var totalOutput=0;var toolSteps=0;var prematureCompletions=0;string? requestId=null;
        var task=new{context.FeatureRequest,task=new{context.TaskTitle,context.TaskDescription,context.AcceptanceCriteria},context.AttemptNumber,context.RevisionNumber,context.ReviewerFeedback,context.EarlierApprovedSummaries,tools=new[]{"list_files","read_file","search_text","apply_patch","get_diff","run_command"},protocol=new{toolCalls=new{type="tool_calls",calls=new[]{new{id="call-1",tool="read_file",arguments=new{path="README.md",query=(string?)null,patch=(string?)null,executable=(string?)null,arguments=(string[]?)null,workingDirectory=(string?)null,timeoutSeconds=(int?)null}}},summary=(string?)null,validationNotes=(string[]?)null,knownLimitations=(string[]?)null},complete=new{type="complete",calls=(object?)null,summary="Implemented the task.",validationNotes=Array.Empty<string>(),knownLimitations=Array.Empty<string>()}}};
