    private async Task<RepositoryToolResult> Execute(ToolCall call,WorkspaceReference workspace,CancellationToken ct){try{return call.Tool switch{"list_files"=>await tools.ListFilesAsync(workspace,Arg(call,"path","."),ct),"read_file"=>await tools.ReadFileAsync(workspace,Arg(call,"path"),ct),"search_text"=>await tools.SearchTextAsync(workspace,Arg(call,"query"),Arg(call,"path","."),ct),"apply_patch"=>await tools.ApplyPatchAsync(workspace,Arg(call,"patch"),ct),"get_diff"=>await tools.GetDiffAsync(workspace,ct),"run_command"=>await tools.RunCommandAsync(workspace,new(Arg(call,"executable"),Args(call),Arg(call,"workingDirectory","."),IntArg(call,"timeoutSeconds",120)),ct),_=>new(false,string.Empty,"tool_rejected","Unknown tool.")};}catch(Exception ex) when(ex is ArgumentException or IOException or UnauthorizedAccessException){return new(false,string.Empty,"tool_rejected",ex.Message);}}
    private static string Arg(ToolCall call,string name,string? fallback=null)=>call.Arguments.TryGetProperty(name,out var value)&&value.ValueKind==JsonValueKind.String?value.GetString()!:fallback??throw new ArgumentException($"{name} is required.");private static int IntArg(ToolCall call,string name,int fallback)=>call.Arguments.TryGetProperty(name,out var value)&&value.TryGetInt32(out var result)?result:fallback;private static string[] Args(ToolCall call)=>call.Arguments.TryGetProperty("arguments",out var value)&&value.ValueKind==JsonValueKind.Array?value.EnumerateArray().Where(x=>x.ValueKind==JsonValueKind.String).Select(x=>x.GetString()!).ToArray():[];
