    private static CoderResult Failure(string code,string message)=>new(false,string.Empty,[],[],0,null,null,null,code,message);private static string Required(string? value,string message)=>string.IsNullOrWhiteSpace(value)?throw new InvalidDataException(message):value.Trim();internal const string StructuredOutputSchema="""{"type":"object","additionalProperties":false,"required":["type","calls","summary","validationNotes","knownLimitations"],"properties":{"type":{"enum":["tool_calls","complete"]},"calls":{"type":["array","null"],"items":{"type":"object","additionalProperties":false,"required":["id","tool","arguments"],"properties":{"id":{"type":"string"},"tool":{"type":"string"},"arguments":{"type":"object","additionalProperties":false,"required":["path","query","patch","executable","arguments","workingDirectory","timeoutSeconds"],"properties":{"path":{"type":["string","null"]},"query":{"type":["string","null"]},"patch":{"type":["string","null"]},"executable":{"type":["string","null"]},"arguments":{"type":["array","null"],"items":{"type":"string"}},"workingDirectory":{"type":["string","null"]},"timeoutSeconds":{"type":["integer","null"]}}}}}},"summary":{"type":["string","null"]},"validationNotes":{"type":["array","null"],"items":{"type":"string"}},"knownLimitations":{"type":["array","null"],"items":{"type":"string"}}}}""";private static string Load(string version)=>PromptLoader.Load(version);
